import React, { useState, useEffect } from 'react'
import Navbar from '../components/Navbar'
import Footer from '../components/Footer'
import Card from '../components/Card'
import Carousel from '../components/Carousel'

export default function Home() {
    
    const [foodCategory, setfoodCategory] = useState([]);
    const [foodItem, setfoodItem] = useState([]);

   const loadData = async () => {
    try {
        let response = await fetch("http://localhost:5000/api/data", {
            method: "POST",
            headers: {
                'Content-Type': 'application/json'
            }
        });
        response = await response.json();
        setfoodItem(response.food_items); // or correct key
        setfoodCategory(response.foodCategory); // or correct key
    } catch (error) {
        console.error("Failed to load data:", error);
    }
}

  

        return (
            <div>

                <div> <Navbar /></div>
                <div> <Carousel /> </div>
                <div className='container' >
                    {
                        Array.isArray(foodCategory) && foodCat.length > 0
                            ? foodCategory.map((data, idx) => (
                                <div key={idx}>Hello World</div>
                            ))
                            : <div>No Categories Found</div>
                    }

                    <Card />
                </div>

                <div> <Footer /> </div>

            </div>
        )
    }
